def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_d = 0
    my_d = 0
    for a, b in history:
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1

    opp_c = n - opp_d

    w = min(6, n)
    rec_opp_d = 0
    for i in range(n - w, n):
        if history[i][1] == 'D':
            rec_opp_d += 1

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    dd_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_streak += 1
        else:
            break

    forgiven = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'C':
            forgiven += 1

    if opp_d > opp_c * 2 or opp_streak >= 5:
        return 'D'

    if opp_last == 'C':
        if n >= 97:
            if opp_d == 0:
                if rng.random() < 0.3:
                    return 'D'
            elif opp_c >= opp_d and (forgiven >= 2 or my_last == 'D'):
                if rng.random() < 0.6:
                    return 'D'
        elif n >= 95:
            if my_last == 'D' and opp_c >= opp_d and forgiven >= 2:
                if rng.random() < 0.4:
                    return 'D'

    hostile = opp_d > opp_c or rec_opp_d >= 4 or opp_streak >= 4

    if opp_last == 'D':
        if my_last == 'C':
            if opp_d == 1 and opp_c > 8 and forgiven >= 1:
                if rng.random() < 0.2:
                    return 'C'
            return 'D'

        if opp_c > opp_d:
            if dd_streak >= 3:
                return 'C'
            if opp_d <= 2 and dd_streak >= 2:
                if rng.random() < 0.6:
                    return 'C'
            if my_d > opp_d:
                return 'C'

        if hostile:
            if dd_streak >= 3 and (opp_c >= opp_d or my_d > opp_d):
                return 'C'
            if my_d > opp_d + 1:
                if rng.random() < 0.25:
                    return 'C'
            return 'D'

        if opp_d <= 1:
            return 'C'
        if opp_c >= opp_d * 2:
            if rng.random() < 0.5:
                return 'C'
        if rec_opp_d <= 2 and opp_streak <= 2:
            if rng.random() < 0.3:
                return 'C'
        return 'D'

    if my_last == 'D':
        if opp_d == 0 and forgiven >= 3 and n > 70:
            if rng.random() < 0.2:
                return 'D'
        if opp_c > opp_d * 3 and forgiven >= 3 and n > 60:
            if rng.random() < 0.15:
                return 'D'
        return 'C'

    if hostile and rec_opp_d >= 3 and my_d < opp_d:
        if rng.random() < 0.45:
            return 'D'

    return 'C'
